-- Node: marine-cnidarian (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Cnidarian Envenomation — Species","body":"**Jellyfish Classification:**\n\n**Box Jellyfish (Chironex fleckeri):**\n- Long visible tentacles (up to 3m), whip-like marks\n- Immediate severe pain\n- Can cause cardiac arrest within minutes\n\n**Irukandji (Carukia barnesi):**\n- Tiny jellyfish, minimal initial sting\n- Delayed systemic symptoms 30-120 min later\n- Sense of impending doom + hypertension\n\n**Bluebottle / Portuguese Man-of-War (Physalia):**\n- Blue tentacles, common worldwide\n- Painful but rarely life-threatening\n- **Do NOT use vinegar** (causes nematocyst discharge)\n\n**Other Jellyfish:**\n- Most cause local pain and dermatitis only\n- Rarely life-threatening","citation":[1,2,4],"options":[{"label":"Box Jellyfish (tropical Australia)","next":"marine-box-jelly"},{"label":"Irukandji Syndrome (delayed symptoms)","next":"marine-irukandji"},{"label":"Bluebottle / Man-of-War","next":"marine-bluebottle"},{"label":"Other jellyfish (local symptoms only)","next":"marine-jelly-minor"}],"summary":"Jellyfish stings: remove tentacles with forceps, rinse with vinegar (acetic acid) — NOT fresh water","safetyLevel":"warning"}'::jsonb
WHERE id = 'marine-cnidarian' AND tree_id = 'marine-envenomation';

-- Node: marine-box-jelly (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Box Jellyfish — Emergency Management","body":"**Prehospital First Aid (ANZCOR):**\n1. Remove from water, call for help\n2. **Douse with vinegar for 30 seconds** (neutralizes undischarged nematocysts)\n3. Pick off remaining tentacles (safe for rescuer after vinegar)\n4. Apply ice packs for analgesia\n5. **Begin CPR if arrest** — may need prolonged resuscitation\n\n**ED Management:**\n- IV access, cardiac monitoring, resuscitation equipment ready\n- Analgesia: IV opioids titrated to effect (may need large doses)\n\n**Box Jellyfish Antivenom (CSL):**\n| Indication | Dose |\n|------------|------|\n| Severe pain unrelieved by IV opiates | 1 ampoule in 100mL NS over 20 min |\n| Hemodynamic compromise | 3 ampoules in 100mL NS, may repeat |\n| **Cardiac arrest** | **Up to 6 ampoules rapid IV push** |\n\n*Pediatric = Adult dosing (venom-based, not weight-based)*\n\n**If antivenom fails in arrest:** Give IV magnesium 10 mmol\n\n**Medications:**\n- [Box Jellyfish Antivenom](#/drug/box-jellyfish-antivenom/box jellyfish envenomation): 1-6 ampoules IV\n- [Magnesium sulfate](#/drug/magnesium-sulfate/cardiac-arrest): 10 mmol IV if antivenom fails","citation":[1,4,5,6],"next":"marine-systemic","images":[{"src":"images/marine-envenomation/box-jellyfish.png","alt":"Box jellyfish (Chironex sp.) — cube-shaped bell with tentacles","caption":"Box jellyfish (Chironex sp.) — cube-shaped bell, potent venom. CC BY-SA 2.0."}],"summary":"Box jellyfish (Chironex): potentially lethal — flood with vinegar, antivenom for severe envenomation","safetyLevel":"critical"}'::jsonb
WHERE id = 'marine-box-jelly' AND tree_id = 'marine-envenomation';

-- Node: marine-irukandji (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Irukandji Syndrome — Management","body":"**Clinical Presentation:**\n- Initial sting often unnoticed or mild\n- **Delayed systemic symptoms 30-120 min:**\n  - Sense of impending doom (pathognomonic)\n  - Severe pain: back, limbs, cramping abdomen\n  - Agitation, dysphoria, diaphoresis\n  - **Hypertension and tachycardia**\n\n**Severe Complications (within 4 hours):**\n- Toxic cardiomyopathy\n- Cardiogenic shock or pulmonary edema\n- Intracerebral hemorrhage (uncontrolled HTN)\n\n**Treatment Protocol:**\n1. Vinegar to sting site (no pressure bandage)\n2. **Analgesia:** IV fentanyl 0.5-1.0 mcg/kg q10min — may need large doses\n3. **Antiemetic:** IV ondansetron 4-8mg or promethazine 25mg\n4. **Hypertension control:** IV GTN infusion, titrate to SBP <160 mmHg\n5. **Refractory pain:** IV magnesium 0.2 mmol/kg (max 10 mmol)\n\n**No antivenom available — supportive care only**\n\n*Symptoms typically resolve within 12 hours*\n\n**Medications:**\n- [Fentanyl](#/drug/fentanyl/analgesia): 0.5-1.0 mcg/kg IV q10min\n- [GTN infusion](#/drug/nitroglycerin/hypertension): Titrate to SBP <160\n- [Magnesium sulfate](#/drug/magnesium-sulfate/pain): 0.2 mmol/kg (max 10 mmol)","citation":[1,7],"next":"marine-systemic","calculatorLinks":[{"id":"marine-irukandji-severity","label":"Irukandji Severity Score"}],"summary":"Irukandji syndrome: delayed severe pain, hypertension, heart failure — IV magnesium for pain and HTN","safetyLevel":"critical"}'::jsonb
WHERE id = 'marine-irukandji' AND tree_id = 'marine-envenomation';

-- Node: marine-bluebottle (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Bluebottle / Portuguese Man-of-War","body":"**Important: Do NOT use vinegar (causes nematocyst discharge)**\n\n**First Aid:**\n1. Remove tentacles, rinse with seawater\n2. **Hot water immersion 43-45°C for up to 30 minutes**\n3. Ice if hot water unavailable\n\n**ED Management:**\n- Usually supportive care only\n- Oral/IV analgesia for pain\n- Antihistamines for itching\n- Rarely causes systemic symptoms\n\n**Disposition:**\n- Most patients can be discharged after pain control\n- Return precautions for infection or worsening symptoms","citation":[1,3],"next":"marine-disposition","summary":"Bluebottle/Portuguese man-of-war: hot water immersion (not vinegar) — vinegar may worsen bluebottle stings","safetyLevel":"warning"}'::jsonb
