-- Node: marine-jelly-minor (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Minor Jellyfish Stings","body":"**Local Reaction Only:**\n- Painful dermatitis, linear wheals\n- Usually self-limited\n\n**Treatment:**\n1. Rinse with seawater (not freshwater)\n2. Remove any visible tentacles\n3. **Hot water immersion 40-45°C for 20-30 min** OR vinegar (regional preference)\n4. Topical hydrocortisone for itching\n5. Oral antihistamines\n\n**Do NOT:**\n- Apply pressure bandage\n- Rub with sand or towel\n- Apply freshwater (causes nematocyst discharge)\n\n**Discharge with:**\n- Wound care instructions\n- Return precautions for infection or systemic symptoms","citation":[1,2],"next":"marine-disposition","summary":"Minor jellyfish stings: vinegar, remove tentacles, hot water immersion, NSAIDs for pain","skippable":true}'::jsonb
