-- Node: marine-urchin (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Sea Urchin Injuries","body":"**Presentation:**\n- Multiple spine punctures (usually feet/hands)\n- Intense local pain\n- Dark discoloration (may be dye — resolves in 48h)\n\n**Treatment:**\n1. **Hot water immersion 40-46°C for 30-90 minutes**\n2. Remove all visible spines carefully (avoid fragmentation)\n3. Irrigate and debride wounds\n4. Shaving cream + razor to remove pedicellariae\n5. **Imaging if retained spines suspected**\n\n**Complications (weeks to months later):**\n- Granuloma formation → excision, intralesional steroids\n- Joint involvement → may require synovectomy\n- Hand wounds → often need surgical debridement\n\n**Disposition:**\n- Spines near joints or neurovascular structures: Splint, surgical consult\n- Otherwise discharge with wound care instructions","citation":[1],"next":"marine-disposition","summary":"Sea urchin spines: hot water soak, remove visible spines — deeply embedded spines may need surgical removal","skippable":true}'::jsonb
WHERE id = 'marine-urchin' AND tree_id = 'marine-envenomation';

-- Node: marine-octopus (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Blue-Ringed Octopus — Tetrodotoxin","body":"**Life-threatening — prepare for respiratory support**\n\n**Presentation:**\n- Tiny, often painless bite\n- Symptom onset: 1-2 hours\n- **Progressive ascending paralysis**\n- Respiratory failure\n- **Patient remains conscious despite paralysis**\n\n**First Aid:**\n1. Clean wound with freshwater\n2. **Pressure immobilization bandage** (slows lymphatic spread)\n3. Prepare for respiratory support\n\n**ED Management:**\n- **No antivenom available**\n- **Intubation and mechanical ventilation** for respiratory paralysis\n- Typical ventilation duration: 2-5 days\n- Supportive care only\n\n**Prognosis:**\n- Patients surviving first 24 hours usually recover without deficits\n- Full recovery expected with adequate respiratory support","citation":[1,11,12],"next":"marine-systemic","summary":"Blue-ringed octopus: tetrodotoxin causes ascending paralysis — no antivenom, supportive care and intubation","safetyLevel":"critical"}'::jsonb
WHERE id = 'marine-octopus' AND tree_id = 'marine-envenomation';

